import { chromium } from 'playwright';import fs from 'fs';
const BASE='https://www.statesideqm.com',THEME='158900125851',ROOT='/collections/state-guard-series',OUT='sep18-sg-sidebar-discovery';fs.mkdirSync(OUT,{recursive:true});
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.setDefaultNavigationTimeout(70000);
const u=new URL(ROOT,BASE);u.searchParams.set('preview_theme_id',THEME);await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(1200);
const theme=await p.evaluate(()=>({id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')}));if(theme.id!==THEME)throw new Error('wrong preview '+JSON.stringify(theme));
const rows=await p.evaluate(()=>{const main=document.getElementById('MainContent')||document.body,out=[];for(const a of main.querySelectorAll('a[href]')){const r=a.getBoundingClientRect(),s=getComputedStyle(a);if(r.width<20||r.height<20||s.display==='none'||s.visibility==='hidden')continue;let u;try{u=new URL(a.href,location.origin)}catch{continue}u.searchParams.delete('preview_theme_id');if(!/^\/collections\/(state-guard-series-[^/?#]+|new-jersey-state-guard-naval-militia)$/.test(u.pathname))continue;const label=(a.getAttribute('aria-label')||a.textContent||a.querySelector('img')?.alt||'').replace(/\s+/g,' ').trim();if(label)out.push({label:label.slice(0,180),route:u.pathname})}const seen=new Set();return out.filter(x=>!seen.has(x.route)&&(seen.add(x.route),true))});
const matrix={include:rows.map((x,i)=>({key:String(i+1).padStart(2,'0'),label:x.label,route:x.route}))};fs.writeFileSync(OUT+'/discovery.json',JSON.stringify({theme,count:rows.length,rows,matrix},null,2));fs.appendFileSync(process.env.GITHUB_OUTPUT,'matrix='+JSON.stringify(matrix)+'\n');fs.appendFileSync(process.env.GITHUB_OUTPUT,'count='+rows.length+'\n');console.log('SGSIDEBARDISCOVERY',JSON.stringify({theme,count:rows.length,rows}));await c.close();await b.close();